# Writes the hedra command files of the snowball run: ground.txt (the piste and its banks), mountains.txt,
# pine.txt, ball.txt (the snowball, baked at its largest), mound.txt, rock.txt, spray.txt, chunk.txt,
# snowfall.txt. Run from models/env: /usr/bin/python3 make_env.py.
# hedra: up Z, front -Y (the camera side; glTF z = -hedra y). Colours exact Ice Cream GB.
import math, random

C = {"plum": "0.486 0.247 0.345", "coral": "0.922 0.420 0.435", "peach": "0.976 0.659 0.459",
     "cream": "1.000 0.965 0.827"}
def mat(name, col, emit=False):
    s = f"material new {name} --base-color {C[col]} --no-slot"
    return s + (f" --emission {C[col]}" if emit else "")

# ---- ground: the piste (flat, 11 m wide) between two banks rising 1.5 m to flat shoulders. glTF z from
# -13 (the far edge, where the mountains begin) to +12 (past the bottom of the frame).
open("ground.txt", "w").write(f"""# The piste: a flat snow floor 11 m wide and 25 m long (glTF z -13..12), banks rising 1.5 m over
# 2.5 m on both sides to shoulders out to x +-11. Plain snow: the game's moving pieces carry the speed.
# Only the faces the camera sees are kept. Generated by make_env.py.
new
{mat("Snow", "cream")}
add mesh grid --name Piste --x-subdivisions 4 --y-subdivisions 8 --size 1 --location 0 0.5 0
scale 11 25 1
apply --scale
add mesh grid --name BankR --x-subdivisions 2 --y-subdivisions 8 --size 1 --location 6.75 0.5 0.75
scale 2.5 25 1
apply --scale
active BankR
mode edit
select vert where "pos.x > 0"
translate 0 0 0.75
select vert where "pos.x < 0"
translate 0 0 -0.75
mode object
add mesh grid --name BankL --x-subdivisions 2 --y-subdivisions 8 --size 1 --location -6.75 0.5 0.75
scale 2.5 25 1
apply --scale
active BankL
mode edit
select vert where "pos.x < 0"
translate 0 0 0.75
select vert where "pos.x > 0"
translate 0 0 -0.75
mode object
add mesh grid --name ShoulderR --x-subdivisions 2 --y-subdivisions 8 --size 1 --location 9.5 0.5 1.5
scale 3 25 1
apply --scale
add mesh grid --name ShoulderL --x-subdivisions 2 --y-subdivisions 8 --size 1 --location -9.5 0.5 1.5
scale 3 25 1
apply --scale
select all
material assign Snow
shade flat
export ground.glb
""")

# ---- mountains: a ragged range of faceted peaks behind the far edge, snow caps on rock
rnd = random.Random(5)
m = ["# Mountains: a ragged range of 5-sided peaks 16-19 m behind the camera's middle (glTF z -16..-19),",
     "# bases sunk 3 m (hidden behind the piste's far edge), snow caps on coral rock. Generated by make_env.py.",
     "new", mat("Rock", "coral"), mat("Snow", "cream")]
x = -14.0
i = 0
while x < 14.5:
    r = rnd.uniform(1.8, 3.0); h = rnd.uniform(4.0, 6.2); y = rnd.uniform(16, 19)
    rot = rnd.uniform(0, 72)
    m += [f"add mesh cone --name Peak{i} --vertices 5 --radius1 {r:.2f} --radius2 0 --depth {h:.2f} --location {x:.2f} {y:.2f} {h / 2 - 3:.2f} --rotation 0 0 {rot:.0f}",
          "material assign Rock",
          f"add mesh cone --name Cap{i} --vertices 5 --radius1 {r * 0.42:.2f} --radius2 0 --depth {h * 0.42:.2f} --location {x:.2f} {y - 0.04:.2f} {h - 3 - h * 0.21 + 0.02:.2f} --rotation 0 0 {rot:.0f}",
          "scale 1.06 1.06 1", "material assign Snow"]
    x += rnd.uniform(2.2, 3.4); i += 1
m += ["select all", "shade flat", "export mountains.glb"]
open("mountains.txt", "w").write("\n".join(m) + "\n")

# ---- pine: a trunk, three 7-sided tiers and their snow caps (2.6 m)
open("pine.txt", "w").write(f"""# A snowy pine 2.6 m tall: a plum trunk, three coral 7-sided tiers, a cream snow cap on each.
# Origin on the ground under the trunk. Generated by make_env.py.
new
{mat("Bark", "plum")}
{mat("Needles", "coral")}
{mat("Snow", "cream")}
add mesh cylinder --name Trunk --vertices 6 --radius 0.17 --depth 0.6 --location 0 0 0.3
material assign Bark
add mesh cone --name Low --vertices 7 --radius1 1.0 --radius2 0.1 --depth 1.0 --location 0 0 0.95
material assign Needles
add mesh cone --name Mid --vertices 7 --radius1 0.78 --radius2 0.05 --depth 0.9 --location 0 0 1.5 --rotation 0 0 25
material assign Needles
add mesh cone --name Tip --vertices 7 --radius1 0.52 --radius2 0 --depth 0.8 --location 0 0 2.05 --rotation 0 0 50
material assign Needles
add mesh cone --name SnowLow --vertices 7 --radius1 0.66 --radius2 0.06 --depth 0.55 --location 0 0 1.2
material assign Snow
add mesh cone --name SnowMid --vertices 7 --radius1 0.52 --radius2 0.03 --depth 0.5 --location 0 0 1.72 --rotation 0 0 25
material assign Snow
add mesh cone --name SnowTip --vertices 7 --radius1 0.34 --radius2 0 --depth 0.46 --location 0 0 2.23 --rotation 0 0 50
material assign Snow
select all
shade flat
export pine.glb
""")

# ---- the snowball: baked at its largest (r 1.0) and only ever scaled down, since a splat's disc does
# not grow with its bone. Peach patches of packed snow, two twigs and three pebbles rolled into it,
# so the roll reads.
open("ball.txt", "w").write(f"""# The snowball, r 1.0 (the game scales it 0.4 to 1.15), origin at its centre (the roll's pivot).
# An 80-face ball, a third of its faces packed snow (peach), two twigs and three pebbles stuck in it.
# Generated by make_env.py.
new
{mat("Snow", "cream")}
{mat("Packed", "peach")}
{mat("Twig", "plum")}
add mesh ico-sphere --name Ball --subdivisions 2 --radius 1.0
material assign Snow
active Ball
mode edit
select mode face
select random --ratio 0.3 --seed 4
material assign Packed
mode object
add mesh cube --name TwigA --size 1 --location 0.62 -0.55 0.55 --rotation 30 40 0
scale 0.12 0.12 0.75
add mesh cube --name TwigB --size 1 --location -0.7 0.3 -0.6 --rotation -40 10 60
scale 0.12 0.12 0.7
add mesh ico-sphere --name PebbleA --subdivisions 1 --radius 0.16 --location -0.3 -0.93 -0.1
add mesh ico-sphere --name PebbleB --subdivisions 1 --radius 0.16 --location 0.2 0.5 0.85
add mesh ico-sphere --name PebbleC --subdivisions 1 --radius 0.16 --location 0.9 0.35 -0.25
select TwigA TwigB PebbleA PebbleB PebbleC
apply --scale
material assign Twig
select all
shade flat
export ball.glb
""")

open("mound.txt", "w").write(f"""# A snow mound: a low faceted lump 1.9 x 1.2 m, 0.4 m high (half buried). Generated by make_env.py.
new
{mat("Snow", "cream")}
add mesh ico-sphere --name Mound --subdivisions 1 --radius 0.6
scale 1.6 1.0 0.7
apply --scale
material assign Snow
active Mound
mode edit
select face where "normal.z < -0.3"
delete only-faces
mode object
shade flat
export mound.glb
""")

open("rock.txt", "w").write(f"""# A rock poking out of the snow, 0.8 m, with snow on its top. Generated by make_env.py.
new
{mat("Rock", "coral")}
{mat("Snow", "cream")}
add mesh ico-sphere --name Rock --subdivisions 1 --radius 0.42 --location 0 0 0.12 --rotation 20 10 35
scale 1.2 0.9 0.8
apply --scale
material assign Rock
active Rock
mode edit
select face where "normal.z > 0.6"
material assign Snow
mode object
shade flat
export rock.glb
""")

open("spray.txt", "w").write(f"""# A puff of spray: a ball of snow 0.28 m. Generated by make_env.py.
new
{mat("Snow", "cream")}
add mesh ico-sphere --name Spray --subdivisions 1 --radius 0.14
material assign Snow
shade flat
export spray.glb
""")
open("chunk.txt", "w").write(f"""# A chunk of snowball: a faceted lump 0.5 m, cream and peach. Generated by make_env.py.
new
{mat("Snow", "cream")}
{mat("Packed", "peach")}
add mesh ico-sphere --name Chunk --subdivisions 1 --radius 0.25 --rotation 10 20 30
material assign Snow
active Chunk
mode edit
select face where "normal.x > 0.3"
material assign Packed
mode object
shade flat
export chunk.glb
""")

# ---- snowfall: two identical 6 m fields stacked, falling one field per 4 s: the lower one starts inside
# the ground, the upper one leaves the top of the frame, so the loop has no seam
rnd = random.Random(11)
H, LOOP = 6.0, 48
pts = [(rnd.uniform(-11, 11), rnd.uniform(-10, 13), rnd.uniform(0, H)) for _ in range(50)]
s = ["# Snowfall: two identical 6 m fields of flakes stacked, falling one field per 4 s (48 frames at 12 fps);",
     "# the lower field starts under the ground, the upper leaves the frame: seamless. Generated by make_env.py.",
     "new", "fps 12", f"frame range 0 {LOOP}", mat("Flake", "cream", True)]
names = []
for k in (0, 1):
    for i, (x, y, z) in enumerate(pts):
        n = f"F{i}_{k}"; names.append(n)
        s.append(f"add mesh cube --name {n} --size 0.11 --location {x:.2f} {y:.2f} {z + H * k:.2f}")
s += ["select " + " ".join(names), "active F0_0", "join", "rename F0_0 Snowfall", "material assign Flake",
      "cursor set 0 0 0", "origin set --to cursor",
      "set location 0 0 0", "keyframe insert --channels loc --frame 0",
      f"set location 0 0 {-H}", f"keyframe insert --channels loc --frame {LOOP}",
      "keyframe interpolation linear --all", "frame set 0", "export snowfall.glb --bake-animations"]
open("snowfall.txt", "w").write("\n".join(s) + "\n")
